% !TEX program = lualatex
\documentclass[11pt,a4paper]{article}
\input{../../../_notes-shared/preamble.tex}

\pagestyle{fancy}
\fancyhf{}
\fancyhead[L]{\small HKDSE Physics: Electrical energy and domestic electricity}
\fancyhead[R]{\small Book 4 Ch.22}
\fancyfoot[C]{\thepage}
\renewcommand{\headrulewidth}{0.4pt}

\title{\textbf{Electrical energy and domestic electricity}}
\date{}

\begin{document}
\maketitle
\exreset

%======================================================================
\section{Electric power and energy}

Electric power is the rate of energy transfer:
\[
P=\frac{E}{t}=VI=I^{2}R=\frac{V^{2}}{R}.
\]
Electrical energy transferred in time $t$:
\[
E=Pt=VIt=I^{2}Rt=\frac{V^{2}}{R}\,t.
\]
SI unit of energy: joule (J).

\ex
A rechargeable battery is rated $1.2\,\mathrm{V}$, $2000\,\mathrm{mA\,h}$.
Find the energy stored when fully charged.
\sol
$I=2.0\,\mathrm{A}$, $t=1\,\mathrm{h}=3600\,\mathrm{s}$.
\[
E=VIt=(1.2)(2.0)(3600)=8640\,\mathrm{J}.
\]

%======================================================================
\section{Paying for electricity}

A kilowatt-hour meter measures \textbf{energy} consumed.
\[
1\,\mathrm{kW\,h}=(1000\,\mathrm{W})\times(3600\,\mathrm{s})=3.6\times 10^{6}\,\mathrm{J}.
\]
In practice:
\[
E\,(\mathrm{kW\,h})=P\,(\mathrm{kW})\times t\,(\mathrm{h}).
\]
Convert carefully: $1.5\,\mathrm{W}=0.0015\,\mathrm{kW}$, not $1.5\,\mathrm{kW}$.

\ex
Five $60\,\mathrm{W}$ lamps run for $8\,\mathrm{h}$. Electricity costs $\$1.02$ per kW\,h.
Find the cost.
\sol
\[
E=\Bigl(\frac{60}{1000}\Bigr)(8)\times 5=2.4\,\mathrm{kW\,h},\qquad
\text{cost}=1.02\times 2.4=\$2.45.
\]

\worked{2016}{28}{A}{77}{../2016_q28.png}{%
$E=(1.5\times 10^{-3}\,\mathrm{kW})\times(16\times 30\,\mathrm{h})=0.72\,\mathrm{kW\,h}$.
CO$_2$: $0.72\times 0.8=0.576\,\mathrm{kg}$.
Trap options forget the milli-prefix or the $0.8$ factor. $\Rightarrow$ \textbf{A}.}

%======================================================================
\section{a.c.\ mains: what 220~V, 50~Hz means}

Hong Kong wall sockets supply \textbf{alternating current} (a.c.):
the voltage between live and neutral reverses direction periodically.
A battery supplies \textbf{direct current} (d.c.): one direction only.

Frequency $f=50\,\mathrm{Hz}$ means one full cycle every
\[
T=\frac{1}{f}=\frac{1}{50}=0.020\,\mathrm{s}=20\,\mathrm{ms}.
\]
Ideally the live--neutral voltage is sinusoidal:
\[
V(t)=V_{0}\sin(2\pi f t),
\]
where $V_{0}$ is the \textbf{peak} value.

\begin{center}
\begin{tikzpicture}[x=0.55cm,y=0.55cm]
  \draw[-{Latex}] (0,0) -- (12.2,0) node[right,font=\small] {$t$};
  \draw[-{Latex}] (0,-2.8) -- (0,3.2) node[above,font=\small] {$V$};
  \draw[thick,blue!60!black,domain=0:11.5,samples=200]
    plot (\x,{2.4*sin(deg(2*pi*\x/5.5))});
  \draw[dashed] (0,2.4) -- (11.5,2.4) node[right,font=\scriptsize] {$+V_{0}$};
  \draw[dashed] (0,-2.4) -- (11.5,-2.4) node[right,font=\scriptsize] {$-V_{0}$};
  \draw[dashed,orange!70!black] (0,{2.4/1.414}) -- (11.5,{2.4/1.414})
    node[right,font=\scriptsize] {$V_{\mathrm{rms}}$};
  \draw[{Latex}-{Latex}] (0,-3.05) -- (5.5,-3.05);
  \node[font=\scriptsize] at (2.75,-3.35) {$T=20\,\mathrm{ms}$};
\end{tikzpicture}
\end{center}

\subsection{r.m.s.\ value}
Over a cycle the average of $V(t)$ is zero, but a resistor still heats
because heating depends on $I^{2}R$.
The \textbf{root-mean-square} (r.m.s.) value is the steady d.c.\ voltage
(or current) that would give the \emph{same average heating} in the same resistor.
For a pure sinusoid:
\[
V_{\mathrm{rms}}=\frac{V_{0}}{\sqrt{2}},\qquad
I_{\mathrm{rms}}=\frac{I_{0}}{\sqrt{2}},\qquad
P_{\mathrm{avg}}=V_{\mathrm{rms}}I_{\mathrm{rms}}
\quad\text{(resistive load)}.
\]
Hong Kong's ``$220\,\mathrm{V}$'' means
\[
V_{\mathrm{rms}}=220\,\mathrm{V}
\quad\Rightarrow\quad
V_{0}=220\sqrt{2}\approx 311\,\mathrm{V}.
\]
Meters and appliance ratings quote \textbf{r.m.s.}\ unless labelled otherwise.
Never confuse peak, peak-to-peak ($2V_{0}$), and r.m.s.

\note{``Mains is 220~V so the voltage never exceeds 220~V.''
False: the instantaneous voltage reaches about $\pm 311\,\mathrm{V}$.}

%======================================================================
\section{Live, neutral and earth}

\begin{center}
\begin{tabular}{@{}llp{6.2cm}@{}}
\toprule
Wire & Ideal potential & Role \\
\midrule
\textbf{Live (L)} & swings $\sim\pm 311\,\mathrm{V}$
  (r.m.s.\ $220\,\mathrm{V}$) & delivers high potential from the supply \\
\textbf{Neutral (N)} & near $0\,\mathrm{V}$
  (earthed at substation) & return path for operating current \\
\textbf{Earth (E)} & $0\,\mathrm{V}$ (ground) &
  safety path only --- unused in normal operation \\
\bottomrule
\end{tabular}
\end{center}

\begin{enumerate}
  \item Normal operation: current flows L $\to$ appliance $\to$ N; earth carries
        \textbf{no} current.
  \item Neutral is near earth potential but is \emph{not} the earth wire;
        it is part of the working circuit.
  \item Because the supply is a.c., live is sometimes positive and sometimes
        negative relative to neutral.
\end{enumerate}

\subsection{Hong Kong colour code}
\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Wire & Modern (IEC) & Older (still found) \\
\midrule
Live & brown & red \\
Neutral & blue & black \\
Earth & green--yellow & green (or green--yellow) \\
\bottomrule
\end{tabular}
\end{center}

\subsection{Three-pin plug}
Looking at the \textbf{inside} of a UK/HK 13~A plug (pins pointing away):

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[thick,rounded corners=3pt,fill=gray!8] (-2.4,-2.6) rectangle (2.4,2.8);
  \fill[green!45!black] (-0.35,1.35) rectangle (0.35,2.45);
  \draw[thick] (-0.35,1.35) rectangle (0.35,2.45);
  \node[font=\scriptsize\bfseries,green!30!black] at (0,1.9) {E};
  \node[font=\scriptsize,align=center] at (0,2.85){earth\\{\scriptsize green/yellow}};
  \fill[blue!55!black] (-1.85,-1.55) rectangle (-1.15,-0.35);
  \draw[thick] (-1.85,-1.55) rectangle (-1.15,-0.35);
  \node[font=\scriptsize\bfseries,white] at (-1.5,-0.95) {N};
  \node[font=\scriptsize,align=center] at (-1.5,-2.15){neutral\\{\scriptsize blue}};
  \fill[brown!70!black] (1.15,-1.55) rectangle (1.85,-0.35);
  \draw[thick] (1.15,-1.55) rectangle (1.85,-0.35);
  \node[font=\scriptsize\bfseries,white] at (1.5,-0.95) {L};
  \node[font=\scriptsize,align=center] at (1.5,-2.15){live\\{\scriptsize brown}};
  \draw[thick,fill=yellow!25] (0.55,-0.05) rectangle (1.85,0.55);
  \node[font=\scriptsize] at (1.2,0.25) {fuse};
  \draw[thick] (1.5,-0.35) -- (1.5,-0.05);
  \draw[thick] (1.5,0.55) -- (1.5,0.85) -- (0.55,0.85);
  \node[font=\scriptsize,align=center] at (0,-0.55)
    {fuse sits in the live path};
\end{tikzpicture}
\end{center}

\begin{enumerate}
  \item Earth pin at the top; fuse in the live.
  \item Earth pin is longer so it opens socket shutters and connects first.
  \item Cable clamp must grip the outer sheath.
\end{enumerate}

\note{Earth is \emph{not} the return path for normal current --- that is neutral.
Earth carries current only under a fault (live touching the metal case).}

%======================================================================
\section{Switch and fuse on live}

\begin{enumerate}
  \item \textbf{Switch} must be in the live wire.
        If it were in neutral only, ``off'' would still leave live connected
        to the appliance --- a shock hazard.
  \item \textbf{Fuse} must also be in the live wire.
        Excess current then melts the fuse and isolates high potential.
        A fuse in neutral may leave the case live after it blows.
\end{enumerate}

\begin{center}
\begin{tikzpicture}[x=1.1cm,y=1.0cm,thick]
  \draw[brown!70!black] (0,2.2) -- (8.2,2.2);
  \draw[blue!60!black] (0,0.8) -- (8.2,0.8);
  \draw[green!45!black] (0,-0.4) -- (8.2,-0.4);
  \node[left,font=\small\bfseries,brown!70!black] at (0,2.2) {L};
  \node[left,font=\small\bfseries,blue!60!black] at (0,0.8) {N};
  \node[left,font=\small\bfseries,green!40!black] at (0,-0.4) {E};
  \draw[fill=yellow!30] (1.3,2.05) rectangle (2.3,2.35);
  \node[font=\scriptsize] at (1.8,2.2) {fuse};
  \draw (3.2,2.2) -- (3.5,2.2);
  \draw (3.5,2.2) -- (4.0,2.55);
  \draw (4.2,2.2) -- (4.5,2.2);
  \node[above,font=\scriptsize] at (3.85,2.55) {S};
  \draw[rounded corners=2pt] (5.2,-0.15) rectangle (7.6,2.55);
  \node[font=\scriptsize\bfseries] at (6.4,2.3) {metal case};
  \draw[fill=orange!20] (5.6,0.95) rectangle (7.2,1.85);
  \node[font=\scriptsize,align=center] at (6.4,1.4) {heating\\element};
  \draw[brown!70!black] (4.5,2.2) -- (5.6,2.2) -- (5.6,1.85);
  \draw[blue!60!black] (5.6,0.95) -- (5.6,0.8) -- (0,0.8);
  \draw[green!45!black] (6.4,-0.15) -- (6.4,-0.4);
  \fill (5.6,1.85) circle (1.5pt);
  \fill (5.6,0.95) circle (1.5pt);
  \fill (6.4,-0.15) circle (1.5pt);
\end{tikzpicture}
\end{center}

Normal path: L $\to$ fuse $\to$ switch $\to$ element $\to$ N.
Earth bonded to case; carries current only under fault.

\worked{2024}{31}{A}{45}{../2024_q31.png}{%
(1)~True: fuse (and switch) belong on live so opening isolates high potential.
(2)~True: earth is a safety conductor, not part of the working L--N loop;
the appliance still runs without it (but is unsafe if live touches the case).
(3)~False: a fuse protects against \textbf{excessive current}.
It does not by itself stop a shock from a live case --- earthing is needed so a
live-to-case fault drives a large current that blows the fuse.
$\Rightarrow$ \textbf{A}.}

%======================================================================
\section{Ring main and lighting}

Appliances need the full mains voltage and independent switching, so sockets
and lamps are connected in \textbf{parallel} across L and N.
Adding appliances decreases $R_{\mathrm{eq}}$ and increases total current drawn.

\begin{enumerate}
  \item \textbf{Ring main (sockets):} live (and neutral) form a loop from the
        consumer unit around the sockets and back.
        Each socket is fed by two paths, so cable current is shared;
        thinner cable can serve a given load.
        Typical ring protection $\sim 30\,\mathrm{A}$; plugs still carry their
        own fuse (e.g.\ $13\,\mathrm{A}$).
  \item \textbf{Lighting:} usually a separate radial circuit with a smaller
        fuse/MCB (often $5$--$6\,\mathrm{A}$). Switches sit on the live feed.
\end{enumerate}

\worked{2023}{28}{C}{30}{../2023_q28.png}{%
(1)~True: a.c.\ means live polarity reverses relative to neutral each half-cycle.
(2)~False: the kW\,h meter measures \textbf{energy}, not power.
(3)~True: appliances in parallel; more branches $\Rightarrow$ smaller $R_{\mathrm{eq}}$.
$\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Short circuit versus overload}

\begin{enumerate}
  \item \textbf{Short circuit:} very low-resistance accidental path between
        points at different potential (typically L--N or L--E), bypassing the
        appliance. Current rises hugely almost at once.
  \item \textbf{Overload:} too many appliances (or one oversized load) draw
        more than the cable/fuse rating for a sustained time, without a
        near-zero-resistance fault. Heating builds more gradually.
\end{enumerate}
Both can blow a fuse; a short is more violent and immediate.

Which shorts blow a fuse on live?
\begin{enumerate}
  \item L shorted to N: huge current through the fuse $\Rightarrow$ blows.
  \item L shorted to E: huge current through the fuse $\Rightarrow$ blows
        (how earthing protects you).
  \item N shorted to E: both near $0\,\mathrm{V}$; little extra current through
        the live fuse $\Rightarrow$ fuse usually does \textbf{not} blow.
\end{enumerate}

\worked{2012}{33}{C}{40}{../2012_q33.png}{%
$X$ on neutral, $Y$ on live (after fuse), $Z$ on earth.
(1)~$X$--$Y$: L--N short $\Rightarrow$ blows.
(2)~$Y$--$Z$: L--E short $\Rightarrow$ blows.
(3)~$X$--$Z$: N--E; no large p.d.\ through the live fuse $\Rightarrow$ does not blow.
$\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Fuse, MCB and ELCB}

\begin{center}
\small
\begin{tabular}{@{}p{2.4cm}p{11.2cm}@{}}
\toprule
Device & Function \\
\midrule
\textbf{Fuse} &
  Thin wire melts on overcurrent. One-shot; replace with the \emph{correct}
  rating (never a larger fuse ``to stop nuisance blowing''). \\
\textbf{MCB} &
  Miniature circuit breaker: trips on overcurrent; can be reset.
  Same job as a fuse (short / overload), reusable. \\
\textbf{ELCB / RCD} &
  Compares current in live and neutral. If they differ (leakage to earth
  through a person or damp path), it trips --- even at tens of mA, far below
  what would blow a $13\,\mathrm{A}$ fuse. Protects against shock. \\
\bottomrule
\end{tabular}
\end{center}

\textbf{Choosing a fuse:} operating current $I=P/V$ must sit just below the
fuse rating.
Example: $1760\,\mathrm{W}$ at $220\,\mathrm{V}$ gives $I=8\,\mathrm{A}$ ---
choose $10\,\mathrm{A}$ or $13\,\mathrm{A}$, not $5\,\mathrm{A}$ (nuisance)
and not $30\,\mathrm{A}$ (useless protection).

\ex
Fuses available: $3\,\mathrm{A}$, $5\,\mathrm{A}$, $13\,\mathrm{A}$.
Appliances at $220\,\mathrm{V}$: lamp $48\,\mathrm{W}$, washer $360\,\mathrm{W}$,
hair dryer $1200\,\mathrm{W}$.
Most suitable combination (lamp, washer, dryer)?
\begin{itemize}[leftmargin=1.8em]
  \item[A.] $3$, $3$, $5$
  \item[B.] $3$, $3$, $13$
  \item[C.] $3$, $5$, $13$
  \item[D.] $5$, $5$, $13$
\end{itemize}
\sol
$I=P/V$: $0.22\,\mathrm{A}$, $1.64\,\mathrm{A}$, $5.45\,\mathrm{A}$.
Next suitable rating above each: $3\,\mathrm{A}$, $3\,\mathrm{A}$, $13\,\mathrm{A}$
(not $5\,\mathrm{A}$ for the dryer). $\Rightarrow$ \textbf{B}.

%======================================================================
\section{Double insulation; appliance ratings}

\subsection{Double insulation}
Some appliances have no earth pin (or a plastic dummy pin).
They use \textbf{double insulation}: two independent insulating layers so one
failure cannot make an accessible part live.
Symbol: square inside a square.
Class~I (metal case) needs earth; Class~II is double-insulated.

\subsection{Ratings versus applied voltage}
A lamp marked ``$220\,\mathrm{V}$,\,$100\,\mathrm{W}$'' means:
\begin{enumerate}
  \item designed for $V_{\mathrm{r}}=220\,\mathrm{V}$;
  \item then dissipates $P_{\mathrm{r}}=100\,\mathrm{W}$;
  \item hot resistance $R\approx V_{\mathrm{r}}^{2}/P_{\mathrm{r}}$.
\end{enumerate}
If a different voltage $V$ is applied ($R$ fixed):
\[
P=\frac{V^{2}}{R}=P_{\mathrm{r}}\Bigl(\frac{V}{V_{\mathrm{r}}}\Bigr)^{2},\qquad
I=\frac{V}{R}.
\]
Halving $V$ quarters the power and halves the current.

\ex
An immersion heater of fixed $R$ takes $8\,\mathrm{min}$ to raise water by
$\Delta\theta$ on $220\,\mathrm{V}$. Time for the same $\Delta\theta$ on
$110\,\mathrm{V}$?
\begin{itemize}[leftmargin=1.8em]
  \item[A.] $2\,\mathrm{min}$
  \item[B.] $4\,\mathrm{min}$
  \item[C.] $16\,\mathrm{min}$
  \item[D.] $32\,\mathrm{min}$
\end{itemize}
\sol
Same $\Delta\theta$ needs same energy $E$. With $R$ fixed, $P\propto V^{2}$.
Halving $V$ makes $P\to P/4$, so $t=E/P\to 4\times 8=32\,\mathrm{min}$
$\Rightarrow$ \textbf{D}.

\ex
A hairdryer rated $110\,\mathrm{V}$ draws $I$ and $P$ in Japan.
Connected (unsafely) to $220\,\mathrm{V}$ HK mains with $R$ unchanged:
new current and power?
\begin{itemize}[leftmargin=1.8em]
  \item[A.] $\tfrac12 I$,\ $\tfrac14 P$
  \item[B.] $I$,\ $2P$
  \item[C.] $2I$,\ $P$
  \item[D.] $2I$,\ $4P$
\end{itemize}
\sol
$V\to 2V\Rightarrow I=V/R\to 2I$ and $P=V^{2}/R\to 4P$ $\Rightarrow$ \textbf{D}.

%======================================================================
\section{Summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
Power / energy & $P=VI=I^{2}R=V^{2}/R$,\quad $E=Pt$ \\
Bill unit & $1\,\mathrm{kW\,h}=3.6\times 10^{6}\,\mathrm{J}$ \\
r.m.s.\ (sinusoid) & $V_{\mathrm{rms}}=V_{0}/\sqrt{2}$,\ $P=V_{\mathrm{rms}}I_{\mathrm{rms}}$ \\
Operating current & $I=P/V$ (use r.m.s.\ mains values) \\
Off-rating power & $P=P_{\mathrm{r}}(V/V_{\mathrm{r}})^{2}$ if $R$ fixed \\
Switch \& fuse & always on \textbf{live} \\
Earth & low-$R$ fault path L $\to$ case $\to$ earth; blows fuse \\
ELCB & trips on L--N current imbalance (leakage / shock) \\
Double insulation & Class~II; may have no earth connection \\
\bottomrule
\end{tabular}
\end{center}

\clearpage
\section{Practice}

\mcpractice{2020}{24}{../2020_q24.png}
\mcpractice{2026}{25}{../2026_q25.png}
\mcpractice{ppp}{30}{../ppp_q30.png}

\subsection*{Practice answers}
\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Paper & Q & Key \\
\midrule
2020 & 24 & D \\
2026 & 25 & D \\
ppp & 30 & C \\
\bottomrule
\end{tabular}
\end{center}

\remark{%
\textbf{2020\,Q24:} $b$ and $c$ both high with $S$ closed $\Rightarrow$ live reaches
past the bulb; $d$ not high $\Rightarrow$ break between $c$ and neutral.
Open circuit $c$--$d$.
\textbf{2026\,Q25:} Earth provides a \textbf{low-resistance path} when live touches
the metal case (so a large fault current can blow the fuse).
\textbf{ppp\,Q30:} Worn insulation at $X$ (live, after switch) touching the earthed
case $\Rightarrow$ L--E short through the fuse $\Rightarrow$ blows.}

