\documentclass[11pt,a4paper]{article}
\input{../../../_notes-shared/preamble.tex}

\pagestyle{fancy}
\fancyhf{}
\fancyhead[L]{\small HKDSE Physics: Alternating current and transformers}
\fancyhead[R]{\small Book 4 Ch.22 \&~24}
\fancyfoot[C]{\thepage}
\renewcommand{\headrulewidth}{0.4pt}

\title{\textbf{Alternating current and transformers}}
\date{}

\begin{document}
\maketitle
\exreset

%======================================================================
\section{Alternating current}

\begin{enumerate}
  \item \textbf{d.c.:} charge flows one way (battery).
  \item \textbf{a.c.:} current direction reverses periodically (mains).
\end{enumerate}
Hong Kong mains: $220\,\mathrm{V}$, $50\,\mathrm{Hz}$
--- the ``$220\,\mathrm{V}$'' is the \textbf{r.m.s.}\ value (below), not the peak.

\subsection{Sinusoidal a.c.}
For a resistive load in phase with $V$:
\[
V=V_{0}\sin\omega t,\qquad I=I_{0}\sin\omega t,
\]
with $\omega=2\pi f$. $V_{0}$ and $I_{0}$ are \textbf{peak} values.

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[-{Latex}] (0,0) -- (7.2,0) node[right,font=\small] {$t$};
  \draw[-{Latex}] (0,-1.6) -- (0,1.8) node[above,font=\small] {$V$};
  \draw[dashed] (0,1.2) -- (6.8,1.2);
  \draw[dashed] (0,-1.2) -- (6.8,-1.2);
  \node[right,font=\scriptsize] at (6.85,1.2) {$V_{0}$};
  \node[right,font=\scriptsize] at (6.85,-1.2) {$-V_{0}$};
  \draw[very thick,blue!50!black,domain=0:6.6,samples=200]
    plot (\x,{1.2*sin(deg(\x*pi/1.65))});
  \draw[dashed,orange!70!black] (0,{1.2/1.414}) -- (6.8,{1.2/1.414});
  \node[font=\scriptsize,orange!70!black] at (5.5,1.05) {$V_{\mathrm{rms}}$};
\end{tikzpicture}
\end{center}

\subsection{Peak and r.m.s.}
Average of $\sin\omega t$ over a cycle is zero, so $\langle V\rangle=0$.
Heating still occurs because power depends on $I^{2}$.
Define the \textbf{root-mean-square} so a resistor dissipates the same average
power as on steady d.c.\ of that value:
\[
V_{\mathrm{rms}}=\sqrt{\langle V^{2}\rangle},\qquad
I_{\mathrm{rms}}=\sqrt{\langle I^{2}\rangle}.
\]
For sinusoids:
\[
V_{\mathrm{rms}}=\frac{V_{0}}{\sqrt{2}},\qquad
I_{\mathrm{rms}}=\frac{I_{0}}{\sqrt{2}}.
\]
HK: $V_{\mathrm{rms}}=220\,\mathrm{V}$ $\Rightarrow$ $V_{0}=220\sqrt{2}\approx 311\,\mathrm{V}$.

\subsection{Average power in a resistor}
\[
\langle P\rangle=I_{\mathrm{rms}}^{2}R=\frac{V_{\mathrm{rms}}^{2}}{R}
=V_{\mathrm{rms}}I_{\mathrm{rms}}.
\]
Note: $\langle P\rangle\neq\langle V\rangle\langle I\rangle$ (both zero for pure a.c.).

\note{CRO traces show peak (or peak-to-peak).
``$220\,\mathrm{V}$ mains'' and transformer formulae use r.m.s.\ unless stated.
Convert before using turns ratios.}

\ex
A $3\,\Omega$ resistor is driven by two a.c.\ waveforms.
Type~1: square-like levels $+6\,\mathrm{A}$ and $-2\,\mathrm{A}$ for equal times.
Type~2: sinusoid with peak $5\,\mathrm{A}$.
Find the average power in each case.
\sol
Type~1:
\[
I_{\mathrm{rms}}=\sqrt{\frac{6^{2}+(-2)^{2}}{2}}=\sqrt{20}=2\sqrt{5}\,\mathrm{A},
\quad
\langle P\rangle=I_{\mathrm{rms}}^{2}R=20\times 3=60\,\mathrm{W}.
\]
Type~2:
\[
I_{\mathrm{rms}}=\frac{5}{\sqrt{2}},\quad
\langle P\rangle=\Bigl(\frac{5}{\sqrt{2}}\Bigr)^{2}(3)=\frac{75}{2}=37.5\,\mathrm{W}.
\]

