\section{Transformers}

\subsection{Structure and Faraday's law}
A transformer has a primary coil, a secondary coil, and usually a laminated
\textbf{soft-iron core} linking them.

Alternating primary current $\Rightarrow$ alternating magnetic flux in the core
$\Rightarrow$ changing flux through the secondary $\Rightarrow$ induced secondary
emf (Faraday). Steady d.c.\ in the primary gives steady flux after switch-on,
so $\Delta\Phi/\Delta t=0$ and no sustained secondary emf.

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[thick] (-0.1,-1.3) -- (-0.1,1.3);
  \draw[thick] (0.1,-1.3) -- (0.1,1.3);
  \foreach \y in {-0.9,-0.55,-0.2,0.15,0.5,0.85} {
    \draw[thick] (-0.1,\y) arc (90:270:0.28);
  }
  \foreach \y in {-0.7,-0.25,0.2,0.65} {
    \draw[thick] (0.1,\y) arc (90:-90:0.35);
  }
  \draw[-{Latex}] (-1.6,0.9) -- (-0.95,0.9);
  \draw[-{Latex}] (-0.95,-0.9) -- (-1.6,-0.9);
  \node[font=\scriptsize,align=center] at (-2.15,0) {a.c.\\primary};
  \node[font=\scriptsize] at (-0.75,1.35) {$N_{p}$};
  \node[font=\scriptsize] at (0.85,1.35) {$N_{s}$};
  \draw[-{Latex}] (1.55,0.75) -- (2.3,0.75);
  \draw[-{Latex}] (2.3,-0.75) -- (1.55,-0.75);
  \node[font=\scriptsize,align=center] at (2.85,0) {load\\secondary};
\end{tikzpicture}
\end{center}

\subsection{Ideal turns ratio}
Negligible flux leakage:
\[
\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}.
\]
(All $V$ mean r.m.s.\ unless a question says peak.)

\subsection{Ideal power and current}
For $100\%$ efficiency, $P_{\mathrm{in}}=P_{\mathrm{out}}$:
\[
V_{p}I_{p}=V_{s}I_{s}
\qquad\Rightarrow\qquad
\frac{I_{s}}{I_{p}}=\frac{N_{p}}{N_{s}}=\frac{V_{p}}{V_{s}}.
\]
Compact ideal summary:
\[
\frac{N_{p}}{N_{s}}=\frac{V_{p}}{V_{s}}=\frac{I_{s}}{I_{p}}.
\]

\begin{enumerate}
  \item \textbf{Step-up:} $N_{s}>N_{p}$ $\Rightarrow$ $V_{s}>V_{p}$ and $I_{s}<I_{p}$.
  \item \textbf{Step-down:} $N_{s}<N_{p}$ $\Rightarrow$ $V_{s}<V_{p}$ and $I_{s}>I_{p}$.
\end{enumerate}

\ex
Ideal transformer: $V_{p}=220\,\mathrm{V}$ a.c., $N_{s}=40$.
Two bulbs on the secondary, each rated $10\,\mathrm{V}$, $20\,\mathrm{W}$,
operate at rated values (parallel on $10\,\mathrm{V}$).
Find (a)~$N_{p}$; (b)~$I_{s}$ and $I_{p}$.
\sol
(a)~$V_{s}=10\,\mathrm{V}$:
\[
\frac{N_{p}}{40}=\frac{220}{10}\Rightarrow N_{p}=880.
\]
(b)~$P_{\mathrm{out}}=40\,\mathrm{W}$.
\[
I_{s}=\frac{40}{10}=4\,\mathrm{A},\qquad
I_{p}=\frac{40}{220}\approx 0.182\,\mathrm{A}.
\]

\worked{2023}{29}{A}{55}{../2023_q29.png}{%
Secondary peak on CRO is $V_{s0}=11\,\mathrm{V}$, so
$V_{s,\mathrm{rms}}=11/\sqrt{2}$.
Primary $V_{p,\mathrm{rms}}=220\,\mathrm{V}$, $N_{p}=2000$.
\[
N_{s}=2000\cdot\frac{11/\sqrt{2}}{220}
=\frac{2000\times 11}{220\sqrt{2}}\approx 70.7\approx 71.
\]
$\Rightarrow$ \textbf{A}.
(Choosing $N_{s}=100$ wrongly treats $11\,\mathrm{V}$ as r.m.s.)}

\subsection{Efficiency and losses}
\[
\eta=\frac{P_{\mathrm{out}}}{P_{\mathrm{in}}}\times 100\%
=\frac{V_{s}I_{s}}{V_{p}I_{p}}\times 100\%.
\]
If $\eta\neq 100\%$, do \textbf{not} use $V_{p}I_{p}=V_{s}I_{s}$.
Still $V_{p}/V_{s}\approx N_{p}/N_{s}$ if leakage is small, but
$V_{p}I_{p}\cdot\eta=V_{s}I_{s}$.

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Loss & Improvement \\
\midrule
Coil resistance ($I^{2}R$) & thicker wires \\
Eddy currents in core & laminated core \\
Hysteresis / magnetization of core & soft-iron core \\
Flux leakage & close coupling; good core \\
\bottomrule
\end{tabular}
\end{center}

\worked{2016}{31}{D}{53}{../2016_q31.png}{%
Two bulbs at rated $22\,\mathrm{W}$ each $\Rightarrow$ $P_{\mathrm{out}}=44\,\mathrm{W}$.
$P_{\mathrm{in}}=V_{p}I_{p}=220\times 0.25=55\,\mathrm{W}$.
\[
\eta=\frac{44}{55}\times 100\%=80\%
\Rightarrow\textbf{D}.
\]}

\worked{2017}{30}{D}{54}{../2017_q30.png}{%
Ten bulbs in parallel, each $1.5\,\mathrm{W}$ at rated value
$\Rightarrow P_{\mathrm{out}}=15\,\mathrm{W}$.
$\eta=70\%$ $\Rightarrow P_{\mathrm{in}}=15/0.70\approx 21.43\,\mathrm{W}$.
$I_{p}=P_{\mathrm{in}}/V_{p}=21.43/220\approx 0.097\,\mathrm{A}$ $\Rightarrow$ \textbf{D}.}

%======================================================================
\section{Power transmission with transformers}

Power delivered: $P\approx VI$.
Cable heating loss:
\[
P_{\mathrm{loss}}=I^{2}R_{\mathrm{cable}}.
\]
For fixed $P$, raising transmission voltage lowers $I=P/V$, so $I^{2}R$ loss
falls sharply.

Transformers make this practical on a.c.:
\begin{enumerate}
  \item step-up at the power station (high $V$, low $I$ on the long cables);
  \item step-down near users (safe domestic voltage).
\end{enumerate}

\ex
Power station delivers $1200\,\mathrm{W}$. Cable resistance total $20\,\Omega$.
\begin{enumerate}
  \item Transmit at $200\,\mathrm{V}$ (no transformers).
  \item Step up $1:20$, then step down $20:1$ (ideal transformers).
\end{enumerate}
Compare cable loss and efficiency.
\sol
(a)~$I=P/V=1200/200=6\,\mathrm{A}$.
\[
P_{\mathrm{loss}}=I^{2}R=6^{2}\times 20=720\,\mathrm{W},\quad
\eta=\frac{1200-720}{1200}=40\%.
\]
Consumer voltage: $200-IR=200-120=80\,\mathrm{V}$ (inadequate).

(b)~$V_{\mathrm{cable}}=200\times 20=4000\,\mathrm{V}$.
\[
I=\frac{1200}{4000}=0.3\,\mathrm{A},\quad
P_{\mathrm{loss}}=(0.3)^{2}(20)=1.8\,\mathrm{W},\quad
\eta\approx 99.85\%.
\]
After cable drop $6\,\mathrm{V}$, step-down gives
$V_{\mathrm{out}}\approx 3994/20=199.7\,\mathrm{V}\approx 200\,\mathrm{V}$.

\note{Exam wording: ``transmitted at high voltage because \ldots''
--- almost always: reduce current, hence reduce $I^{2}R$ loss.}

%======================================================================
\section{Summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
Sinusoidal r.m.s. & $V_{\mathrm{rms}}=V_{0}/\sqrt{2}$,\quad $I_{\mathrm{rms}}=I_{0}/\sqrt{2}$ \\
Average power (resistor) & $\langle P\rangle=V_{\mathrm{rms}}I_{\mathrm{rms}}=V_{\mathrm{rms}}^{2}/R$ \\
Ideal transformer & $N_{p}/N_{s}=V_{p}/V_{s}=I_{s}/I_{p}$ \\
Efficiency & $\eta=P_{\mathrm{out}}/P_{\mathrm{in}}$;\quad $\eta V_{p}I_{p}=V_{s}I_{s}$ \\
Cable loss & $P_{\mathrm{loss}}=I^{2}R$; high $V$ $\Rightarrow$ low $I$ \\
\bottomrule
\end{tabular}
\end{center}

